  position: relative;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 16px;
  border-radius: 12px;
  background: linear-gradient(to right, rgb(0 0 153 / 0.14) var(--share, 0%), var(--c-lavender) var(--share, 0%));
