.pager { display: flex; flex-wrap: wrap; gap: 12px; justify-content: space-between; margin-top: 24px; }

/* ---------- Quizzy additions ---------- */

.field-label { font-weight: 600; font-size: 15px; }

.quiz-list { list-style: none; padding: 0; margin: 0; }
.question-list { list-style: none; padding: 0; margin: 0; }

.input--code, .code-block { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 15px; }
.code-block { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; }

.result-card__prefix { font-size: 0.35em; display: block; letter-spacing: 0; }

.screen__kicker { font-weight: 700; font-size: clamp(18px, 1.8vw, 30px); opacity: 0.8; margin-bottom: 0.4em; }


.stage-option__mark {
  border-radius: 1000px;
  padding: 0.2em 0.7em;
  background: var(--c-success);
  color: var(--c-white);
  font-size: 0.55em;
  font-weight: 800;
}

.leader__badge {
  display: inline-block;
  margin-left: 0.4em;
  border-radius: 1000px;
  padding: 0.15em 0.6em;
  background: var(--c-pink);
  color: var(--c-white);
  font-size: 0.55em;
  vertical-align: middle;
}
.leader.is-winner .leader__name::after { content: none; }

/* ---------- Quizzy application additions ---------- */

.quiz-list > li,
.question-list > li { margin: 0; }
.question-list { display: flex; flex-direction: column; gap: 16px; }
.option-row__text { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.option-row .field-label { margin: 0; }
.option-row .checkbox { white-space: nowrap; }
.admin-main--preview { max-width: 700px; }
.preview-head { display: flex; justify-content: space-between; gap: 16px; align-items: center; margin-bottom: 24px; }
.preview-head .logo { font-size: 26px; }
.form-actions { margin-top: 8px; }
.question-item__actions form { margin: 0; }
.question-item__actions .checkbox { justify-content: flex-end; }
.quiz-form-card { max-width: 760px; }
.quiz-title-link { text-decoration: none; }
.quiz-title-link:hover { color: var(--c-pink); }
.list-inline { display: inline; }
.inline-form { display: inline; }
.empty-actions { margin-top: 16px; }

@media (max-width: 760px) {
  .question-item { grid-template-columns: auto 1fr; }
  .question-item__actions { grid-column: 1 / -1; flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: flex-start; }
  .question-item__actions .buttons { justify-content: flex-start; }
  .question-item__actions .checkbox { justify-content: flex-start; }
  .option-row { grid-template-columns: 1fr; }
}

/* Render option letters as decoration so the button's text is just the option text. */
.play-option::before {
  content: attr(data-letter);
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--c-blue);
  color: var(--c-lavender);
  font-family: var(--f-display);
  font-weight: 900;
  font-size: 16px;
}
.play-option.is-picked::before { background: var(--c-lavender); color: var(--c-blue); }
.play-options.is-revealed .play-option.is-correct::before { background: var(--c-white); color: var(--c-success); }
.play-options.is-revealed .play-option.is-picked:not(.is-correct)::before { background: var(--c-white); color: var(--c-pink); }

