     1	<% content_for :title, "Preview · #{@quiz.title}" %>
     2	
     3	<div class="preview-head">
     4	  <%= link_to "← #{@quiz.title}", moderate_quiz_path(@quiz), class: "meta" %>
     5	  <span class="admin-header__tag">Preview</span>
     6	</div>
     7	
     8	<% if @active_questions.empty? %>
     9	  <div class="card result-card">
    10	    <h1>Preview</h1>
    11	    <p>There are no active questions to preview.</p>
    12	    <div class="buttons" style="justify-content: center">
    13	      <%= link_to "Back to quiz", moderate_quiz_path(@quiz), class: "btn btn--ghost" %>
    14	    </div>
    15	  </div>
    16	<% elsif @finished %>
    17	  <div class="card result-card">
    18	    <div class="result-card__label">Preview complete</div>
    19	    <div class="result-card__score">Score: <%= @score %>/<%= @total %></div>
    20	    <div class="buttons mt-2" style="justify-content: center">
    21	      <%= button_to "Start over",
    22	                    restart_moderate_quiz_preview_path(@quiz),
    23	                    method: :post,
    24	                    class: "btn btn--pink",
    25	                    form: { data: { turbo: false } } %>
    26	    </div>
    27	  </div>
    28	<% else %>
    29	  <% selected_option = @question.options.find { |option| option.id == @selected_option_id } %>
    30	  <% answered = selected_option.present? %>
    31	
    32	  <div class="play-question__num">Question <%= @current_index + 1 %> of <%= @active_questions.length %></div>
    33	  <div class="play-question__body"><%= @question.body %></div>
    34	
    35	  <div class="play-options <%= "is-locked is-revealed" if answered %>">
    36	    <% @question.options.each_with_index do |option, option_index| %>
    37	      <% if answered %>
    38	        <button type="button"
    39	                class="play-option <%= "is-picked" if option.id == selected_option.id %> <%= "is-correct" if option.correct? %>"
    40	                data-letter="<%= option_letter(option_index) %>"
    41	                aria-label="<%= option.body %>"
    42	                disabled>
    43	          <span class="play-option__title"><%= option.body %></span>
    44	          <% if option.correct? %>
    45	            <span class="play-option__mark">Correct</span>
    46	          <% end %>
    47	        </button>
    48	      <% else %>
    49	        <%= button_to answer_moderate_quiz_preview_path(@quiz),
