    52	                      class: "play-option",
    53	                      data: { letter: option_letter(option_index) },
    54	                      aria: { label: option.body },
    55	                      form: { data: { turbo: false } } do %>
    56	          <span class="play-option__title"><%= option.body %></span>
    57	        <% end %>
    58	      <% end %>
    59	    <% end %>
    60	  </div>
    61	
    62	  <% if answered %>
