// Live game screens poll a small JSON endpoint and replace only the live
// region when the game state changes. Player answers are posted with fetch so
// phones never need a page reload while a question is open.
function quizzyCsrfToken() {
  const meta = document.querySelector('meta[name="csrf-token"]');
  return meta ? meta.content : "";
}

function applyLiveState(container, data) {
  if (!container || !data) return;

  if (data.signature && container.dataset.signature !== data.signature) {
    container.innerHTML = data.content || "";
    container.dataset.signature = data.signature;
  }

  if (typeof data.players_count !== "undefined") {
    container.querySelectorAll("[data-live-players]").forEach((element) => {
      element.textContent = data.players_count;
    });
  }

  if (typeof data.answers_count !== "undefined") {
    container.querySelectorAll("[data-live-answers]").forEach((element) => {
      element.textContent = data.answers_count;
    });
  }
}

async function refreshLiveState(container) {
  if (!container || !document.body.contains(container)) return;

  try {
    const response = await fetch(container.dataset.liveStateUrl, {
      headers: {
        "Accept": "application/json",
        "X-CSRF-Token": quizzyCsrfToken()
      },
      credentials: "same-origin",
      cache: "no-store"
    });

    if (response.ok) {
      applyLiveState(container, await response.json());
    }
  } catch (_error) {
    // A later poll will retry; a transient conference Wi-Fi drop should not
    // interrupt the game screen.
  }
}

function startLivePolling(container) {
  if (!container || container.dataset.livePolling === "true") return;
  container.dataset.livePolling = "true";

  const poll = async () => {
    await refreshLiveState(container);

    if (document.body.contains(container)) {
      window.setTimeout(poll, 900);
    }
  };

  window.setTimeout(poll, 250);
}

function initializeLiveRegions() {
  document.querySelectorAll("[data-live-state-url]").forEach(startLivePolling);
}

document.addEventListener("DOMContentLoaded", initializeLiveRegions);
document.addEventListener("turbo:load", initializeLiveRegions);

document.addEventListener("submit", (event) => {
  const form = event.target.closest("[data-live-answer-form]");
  if (!form) return;

  event.preventDefault();
  event.stopImmediatePropagation();

  const container = document.querySelector("[data-live-state-url]");
  const submit = form.querySelector('button[type="submit"], input[type="submit"]');
  if (submit) submit.disabled = true;

  fetch(form.action, {
    method: "POST",
    headers: {
      "Accept": "application/json",
      "X-CSRF-Token": quizzyCsrfToken()
    },
    body: new FormData(form),
    credentials: "same-origin"
  })
    .then(async (response) => {
      const contentType = response.headers.get("content-type") || "";
      if (response.ok && contentType.includes("application/json")) {
        applyLiveState(container, await response.json());
      } else {
        window.location.reload();
      }
    })
    .catch(() => {
      // Fall back to a normal form submission if the fetch itself fails.
      form.removeAttribute("data-live-answer-form");
      form.submit();
    })
    .finally(() => {
      if (submit && document.body.contains(submit)) submit.disabled = false;
    });
});
